from robot.libraries.BuiltIn import BuiltIn
from taf.ul.kpi_selector.utilities.exceptions import IncorrectBTSType

from taf.ul.kpi_selector.utilities.kpi_logger import log_input_and_output


@log_input_and_output
def get_details_to_login_from_init(service, gnb_id=0, enb_id=0, bts_type="GNB"):
    """
    Get details to log in from given service.

    :param service: Two types of services to be chosen: 'http' or 'ssh'
    :type service: str
    :param gnb_id: gnb id user wants to get details to (0 at default).
    :type gnb_id : int/str
    :param enb_id: enb id user wants to get details to (0 at default).
    :type enb_id: int/str
    :param bts_type: GNB or ENB (GNB at default)
    :type bts_type: str
    :return: tuple of str (address, username, password) e.g. ('192.168.255.129', 'toor4nsn', 'oZPS0POrRieRtu')
             or (address, username, password, port) e.g. ('192.168.255.129', 'toor4nsn', 'oZPS0POrRieRtu', '443')
    :raises AttributeError when there is no service requested by user
    """
    if service == 'http':
        details_to_login = BuiltIn().get_variable_value("${{tl.gnbs[{0}].cu.oam_http_connection_details}}".
                                                        format(gnb_id))
        return details_to_login.addr, details_to_login.username, details_to_login.password, details_to_login.port

    elif service == 'ssh':
        return _get_details_to_login_via_ssh(gnb_id=gnb_id, enb_id=enb_id, bts_type=bts_type)
    else:
        raise AttributeError("There is no service: {}. Only supported: 'http' and 'ssh'".format(service))


def _get_details_to_login_via_ssh(gnb_id=0, enb_id=0, bts_type="GNB"):
    """
    Get details to login via ssh.

    :param gnb_id: gnb id user wants to get details to (0 at default).
    :type gnb_id : int/str
    :param enb_id: enb id user wants to get details to (0 at default).
    :type enb_id: int/str
    :param bts_type: GNB or ENB (GNB at default)
    :type bts_type: str
    :return: tuple of str (address, username, password) e.g. ('192.168.255.129', 'toor4nsn', 'oZPS0POrRieRtu')
    """
    if bts_type == "GNB":
        try:
            details_to_login = BuiltIn().get_variable_value("${{tl.gnbs[{0}].dus[0].airscale.common_units[0]."
                                                            "lmp_connection}}".format(gnb_id))
            return details_to_login.addr, details_to_login.username, details_to_login.password
        except AttributeError:
            details_to_login = BuiltIn().get_variable_value("${{tl.gnbs[{0}].dus[0].airscale.core_units[0]."
                                                            "lmp_connection}}".format(gnb_id))
            return details_to_login.addr, details_to_login.username, details_to_login.password

    if bts_type == "ENB":
        details_to_login = BuiltIn().get_variable_value("${{tl.enbs[{0}].airscale.common_units[0]."
                                                        "lmp_connection}}".format(enb_id))
        return details_to_login.addr, details_to_login.username, details_to_login.password
    raise IncorrectBTSType("BTS type is neither GNB nor ENB.")
